const item = $input.first().json;
const logoMime = item.logoMime || 'image/jpeg';
const logoBase64 = item.logoBase64 || '';
const productoMime = item.productoMime || 'image/jpeg';
const productoBase64 = item.productoBase64 || '';
const productId = item.productId || 'PRODUCTO';
const descripcion = (item.DESCRIPCION || item.DESCRIPCIÓN) ? String(item.DESCRIPCION || item.DESCRIPCIÓN).trim() : '';
const hasSpecs = descripcion.length > 0;
const SPEC_AREA = 150;

// Lógica de Mensaje Gancho Unificada
const ganchos = {
  "ROPA": ["💜 Tu mejor estilo. Precio justo.", "🛡️ Inversión inteligente para tu armario.", "⚡ Presencia total. Cero especulación.", "🔄 Renueva tu imagen. Calidad que dura.", "🎯 Exclusividad diaria a tu alcance."],
  "ZAPATOS": ["✨ Comodidad y elegancia en cada paso.", "🛡️ Hechos para durar y destacar.", "⚡ Pisa fuerte. Calidad que ahorra.", "⚖️ Soporte total. Cero especulación.", "🏆 Pasos firmes, inversión segura."],
  "CARTERAS": ["🎒 Espacio y diseño a tu medida.", "🛡️ Resistencia diaria, elegancia total.", "🎯 Funcionalidad y estilo a precio justo.", "💎 Lujo y orden en tus manos.", "🌟 Excelencia en cada costura."],
  "TECNOLOGIA": ["🚀 Moderniza tu vida sin pagar de más.", "⚡ Rendimiento total. 100% innovación.", "🛡️ Máxima potencia, ahorro inteligente.", "🌐 El futuro en tus manos, hoy.", "🔋 Tecnología real. Paga lo justo."],
  "ACCESORIOS": ["✨ El detalle que lo cambia todo.", "🎯 Gran impacto, inversión mínima.", "💎 Exclusividad que eleva tu imagen.", "💜 Calidad que se nota al instante.", "👑 Elegancia pura, precio sin trucos."]
};
let copyText = item.copyText;
if (!copyText) {
    const cat = item.CATEGORÍA || item.category || item.categoryRaw || 'GENERAL';
    const opts = ganchos[cat.toUpperCase()];
    copyText = (opts && opts.length > 0) ? opts[Math.floor(Math.random() * opts.length)] : '🛍️ CALIDAD Y ESTILO AL MEJOR PRECIO ✨';
}

// CORRECCIÓN DEFINITIVA: Solo los productos en la hoja manual (specialSale) 
// reciben el color verde y el texto "REBAJA ESPECIAL".
if (item.specialSale === true) {
    copyText = 'REBAJA ESPECIAL';
}
const talla = item.talla || '';

// --- 1. EXTRACCIÓN ROBUSTA DE DATOS ---
const actualCup = item.cupPrice || item["ACTUAL CUP"] || 0;
const actualUsd = item.usdPrice || item["ACTUAL USD"] || 0;
const maxCup = item["MAX HIST CUP"] || actualCup;
const maxUsd = item["MAX HIST USD"] || actualUsd;

const cupRaw = Math.ceil(Number(actualCup));
const cupPrice = cupRaw > 0 ? '$' + cupRaw.toLocaleString('en-US') + ' CUP' : '0 CUP';
const formatUsd = (val) => {
    const num = Number(val);
    if (isNaN(num) || num <= 0) return '0 USD';
    return '$' + (num % 1 === 0 ? num.toFixed(0) : num.toFixed(2)) + ' USD';
};
const usdPrice = formatUsd(actualUsd);

// La visibilidad del banner rojo central depende de isSale (Cualquier rebaja)
const isCupDiscount = (maxCup > actualCup);
const isUsdDiscount = (maxUsd > actualUsd);
const isDiscountValid = isCupDiscount || isUsdDiscount;

// --- 2. LÓGICA DINÁMICA DE LAYOUT ---
const footerHeight = isDiscountValid ? 440 : 320;
const finalFooterHeight = hasSpecs ? footerHeight + SPEC_AREA : footerHeight;
const productAreaHeight = 1440 - finalFooterHeight;
const productImgMaxHeight = productAreaHeight - 40; 

// --- 3. CONSTRUCCIÓN DE COMPONENTES DINÁMICOS ---
let priceHtml = '';
let bannerHtml = '';

if (isDiscountValid) {
    let oldCupHtml = '';
    let oldUsdHtml = '';
    let bannerAmountsStr = '';

    if (isCupDiscount) {
        const diffCupVal = maxCup - actualCup;
        const oldCupStr = '$' + Math.ceil(maxCup).toLocaleString('en-US') + ' CUP';
        const diffCupStr = '$' + Math.ceil(diffCupVal).toLocaleString('en-US') + ' CUP';
        oldCupHtml = '<span class="old-price">' + oldCupStr + '</span>';
        bannerAmountsStr += diffCupStr;
    }

    if (isUsdDiscount) {
        const diffUsdVal = maxUsd - actualUsd;
        const oldUsdStr = formatUsd(maxUsd);
        const diffUsdStr = formatUsd(diffUsdVal);
        oldUsdHtml = '<span class="old-price">' + oldUsdStr + '</span>';
        if (isCupDiscount) bannerAmountsStr += ' <span class="banner-sep">/</span> ' + diffUsdStr;
        else bannerAmountsStr += diffUsdStr;
    }

    priceHtml = '<div class="price-container">' +
        '<span class="price-val">' + cupPrice + '</span>' +
        oldCupHtml +
        '<span class="price-sep">/</span>' +
        '<span class="price-val">' + usdPrice + '</span>' +
        oldUsdHtml +
    '</div>';

    bannerHtml = '<div class="discount-banner">' +
        '<span class="banner-title">AHORRAS</span>' +
        '<span class="banner-amounts">' + bannerAmountsStr + '</span>' +
    '</div>';
} else {
    priceHtml = '<div class="price-container"><span class="price-val">' + cupPrice + '</span><span class="price-sep">/</span><span class="price-val">' + usdPrice + '</span></div>';
}

let tallaHtml = '';
if (talla) {
    tallaHtml = '<div class="talla-tag"><span class="talla-label">Talla: </span><span class="talla-val">' + talla + '</span></div>';
}
let specsHtml = '';
if (hasSpecs) {
    const specTop = isDiscountValid ? '335px' : '215px';
    specsHtml = '<div class="spec-block" style="top: ' + specTop + '; height: 150px;">' + descripcion + '</div>';
}

// --- 4. RENDERIZADO DOM & CSS ---
const html = '<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Archivo+Black&family=Open+Sans:wght@200;400;600;700;800;900&display=swap" rel="stylesheet"><style>' +
'* { margin: 0; padding: 0; box-sizing: border-box; } ' +
'body, html { width: 1080px; height: 1440px; overflow: hidden; background-color: #6d1e68; font-family: "Open Sans", sans-serif; } ' +
'.main-canvas { width: 1080px; height: 1440px; display: flex; flex-direction: column; position: relative; } ' +
'.logo-raw { position: absolute; top: 50px; left: 50px; width: 180px; z-index: 100; } ' +
'.product-area { position: absolute; top: 0; left: 0; width: 1080px; height: ' + productAreaHeight + 'px; display: flex; justify-content: center; align-items: center; padding: 20px; } ' +
'.product-img { max-width: 1040px; max-height: ' + productImgMaxHeight + 'px; object-fit: contain; filter: drop-shadow(0px 35px 65px rgba(0,0,0,0.55)); } ' +
'.info-footer { position: absolute; bottom: 0; left: 0; width: 1080px; height: ' + finalFooterHeight + 'px; background-color: #ffffff; box-shadow: 0px -15px 40px rgba(0,0,0,0.2); z-index: 10; } ' +
'.divider-img { position: absolute; top: 0; left: 5%; width: 90%; height: 3px; background: linear-gradient(90deg, rgba(160,160,160,0) 0%, rgba(160,160,160,0.6) 50%, rgba(160,160,160,0) 100%); z-index: 15; } ' +
'.top-left-block { position: absolute; top: 25px; left: 30px; display: flex; flex-direction: column; align-items: flex-start; } ' +
'.name-tag { font-family: "Open Sans", sans-serif; font-size: 38px; font-weight: 900; color: #000000; text-decoration: underline; max-width: 1020px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-bottom: 2px; line-height: 1.1; text-transform: uppercase; } ' +
'.talla-tag { margin-top: 5px; } ' +
'.talla-label { font-family: "Open Sans", sans-serif; font-size: 32px; font-weight: 700; color: #333333; } ' +
'.talla-val { font-family: "Open Sans", sans-serif; font-size: 32px; font-weight: 700; color: #555555; } ' +
'.divider-title { position: absolute; top: 110px; left: 5%; width: 90%; height: 3px; background: linear-gradient(90deg, rgba(160,160,160,0) 0%, rgba(160,160,160,0.6) 50%, rgba(160,160,160,0) 100%); z-index: 15; } ' +
'.center-block { position: absolute; top: 135px; left: 50%; transform: translateX(-50%); width: 100%; display: flex; justify-content: center; align-items: center; } ' +
'.price-container { display: flex; align-items: baseline; gap: 12px; } ' +
'.price-val { font-family: "Archivo Black", sans-serif; font-size: 52px; font-weight: 900; color: #e87b04; line-height: 0.85; white-space: nowrap; text-shadow: 2px 3px 4px rgba(0,0,0,0.2); } ' +
'.old-price { font-family: "Open Sans", sans-serif; font-size: 30px; color: #999999; text-decoration: line-through; text-decoration-thickness: 3px; font-weight: 700; white-space: nowrap; margin-bottom: -2px; } ' +
'.price-sep { font-family: "Open Sans", sans-serif; font-size: 70px; font-weight: 200; color: #e87b04; margin: 0 10px; line-height: 0.8; text-shadow: 1px 2px 3px rgba(0,0,0,0.1); } ' +
'.discount-banner { position: absolute; top: 260px; left: 0; width: 1080px; background: linear-gradient(90deg, #d32f2f 0%, #f44336 50%, #d32f2f 100%); color: #ffffff; display: flex; justify-content: center; align-items: center; padding: 6px 0; z-index: 20; box-shadow: 0px 4px 15px rgba(0,0,0,0.15); gap: 20px; } ' +
'.banner-title { font-family: "Archivo Black", sans-serif; font-size: 34px; text-transform: uppercase; letter-spacing: 2px; } ' +
'.banner-amounts { font-family: "Archivo Black", sans-serif; font-size: 45px; display: flex; align-items: center; text-shadow: 2px 3px 6px rgba(0,0,0,0.45); } ' +
'.banner-sep { font-weight: 200; font-size: 55px; margin: 0 10px; font-family: "Open Sans", sans-serif; } ' +
'.slogan-tag { position: absolute; bottom: 25px; left: 0; width: 100%; font-family: "Open Sans", sans-serif; font-size: 34px; font-weight: 800; color: #444444; text-align: center; text-transform: uppercase; }' +
'.slogan-tag.rebaja { background: #2e7d32; color: #ffffff; width: auto; left: 50%; transform: translateX(-50%); padding: 12px 40px; border-radius: 12px; font-weight: 900; letter-spacing: 2px; box-shadow: 0px 4px 10px rgba(0,0,0,0.2); }' +
'.spec-block { position: absolute; left: 0; width: 100%; display: flex; justify-content: center; align-items: center; padding: 0 60px; font-family: "Open Sans", sans-serif; font-size: 26px; font-weight: 600; color: #333333; text-align: center; line-height: 1.5; word-wrap: break-word; overflow-wrap: break-word; } ' +
'</style></head><body><div class="main-canvas">' +
'<img src="data:' + logoMime + ';base64,' + logoBase64 + '" class="logo-raw" />' +
'<div class="product-area"><img src="data:' + productoMime + ';base64,' + productoBase64 + '" class="product-img" /></div>' +
'<div class="info-footer">' +
'<div class="divider-img"></div>' +
'<div class="top-left-block"><div class="name-tag">' + productId + '</div>' + tallaHtml + '</div>' +
'<div class="divider-title"></div>' +
'<div class="center-block">' + priceHtml + '</div>' +
'<div class="divider-bottom"></div>' +
bannerHtml +
specsHtml +
'<div class="slogan-tag' + (item.specialSale === true ? ' rebaja' : '') + '">' + copyText + '</div></div></div>' +
'<script>' +
'function fitText() {' +
'  const pContainer = document.querySelector(".price-container");' +
'  if (pContainer && pContainer.offsetWidth > 1000) {' +
'    const ratio = 1000 / pContainer.offsetWidth;' +
'    pContainer.style.transform = "scale(" + ratio + ")";' +
'    pContainer.style.transformOrigin = "center center";' +
'  }' +
'}' +
'window.onload = fitText;' +
'</script></body></html>';

return [{ json: { ...item, html: html } }];
